// NOTE: You do not have permission to overwrite this file. Please ask a human operator to perform the changes for you.
{
    "$schema": "vendor/infection/infection/resources/schema.json",
    "source": {
        "directories": [
            "REPLACE_WITH_PRODUCTION_SOURCE_ROOT"
        ]
    },
    "mutators": {
        "@default": true
    },
    "minMsi": 80,
    "minCoveredMsi": 80,
    "timeout": 30,
    "tmpDir": "build/infection-tmp",
    "logs": {
        "text": "build/infection/escaped.log",
        "summary": "build/infection/summary.log",
        "perMutator": "build/infection/per-mutator.md",
        "json": "build/infection/infection.json"
    },
    "testFrameworkExtraArgs": "--no-extensions",
    "testFramework": "phpunit"
}

name: Fuzz (sql-semantics)

on:
  schedule:
    - cron: '17 4 * * *'
  workflow_dispatch:
    inputs:
      max_runs:
        description: Maximum mutation iterations after the initial corpus is replayed
        required: true
        default: '10000'
        type: string
      mysql_version:
        description: MySQL release whose grammar the MySQL target parses with
        required: true
        default: '8.4.7'
        type: string

permissions:
  contents: read

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: false

env:
  COMPOSER_NO_INTERACTION: '1'
  MYSQL_VERSION: ${{ inputs.mysql_version || '8.4.7' }}

jobs:
  roundtrip:
    if: github.ref == 'refs/heads/main'
    name: Semantic round trip / ${{ matrix.target.database }}
    runs-on: ubuntu-latest
    timeout-minutes: 60
    permissions:
      contents: read
      issues: write
    strategy:
      fail-fast: false
      matrix:
        target:
          - { database: mysql, package: sql-semantics-mysql, script: fuzz_mysql_roundtrip.php, extensions: 'mbstring, pcntl, zlib' }
          - { database: pg, package: sql-semantics-postgres, script: fuzz_pg_roundtrip.php, extensions: 'mbstring, pcntl, zlib' }
          - { database: sqlite, package: sql-semantics-sqlite, script: fuzz_sqlite_roundtrip.php, extensions: 'mbstring, pcntl, zlib' }
    defaults:
      run:
        working-directory: packages/${{ matrix.target.package }}
    steps:
      - name: Check out the repository
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
      - name: Set up PHP
        uses: shivammathur/setup-php@f3e473d116dcccaddc5834248c87452386958240
        with:
          php-version: '8.5'
          extensions: ${{ matrix.target.extensions }}
          coverage: none
      - name: Install dependencies
        uses: ramsey/composer-install@65e4f84970763564f46a70b8a54b90d033b3bdda
        with:
          working-directory: packages/${{ matrix.target.package }}
          dependency-versions: locked
          composer-options: --prefer-dist
          require-lock-file: true
      - name: Check runtime platform requirements
        run: composer check-platform-reqs --no-dev
      - name: Validate the manual run budget
        env:
          FUZZ_MAX_RUNS: ${{ inputs.max_runs || '10000' }}
        run: |
          case "$FUZZ_MAX_RUNS" in
            ''|*[!0-9]*) echo 'max_runs must be a positive integer.' >&2; exit 2 ;;
          esac
          if [ "${#FUZZ_MAX_RUNS}" -gt 8 ] || [ "$FUZZ_MAX_RUNS" -lt 1 ]; then
            echo 'max_runs must be between 1 and 99999999.' >&2
            exit 2
          fi
      - name: Restore the evolving raw-input corpus
        uses: actions/cache/restore@55cc8345863c7cc4c66a329aec7e433d2d1c52a9
        with:
          path: packages/${{ matrix.target.package }}/fuzz/corpus/${{ matrix.target.database }}
          key: sql-semantics-corpus-v1-${{ matrix.target.database }}-${{ env.MYSQL_VERSION }}-${{ github.run_id }}-${{ github.run_attempt }}
          restore-keys: sql-semantics-corpus-v1-${{ matrix.target.database }}-${{ env.MYSQL_VERSION }}-
      - name: Restore grammar coverage snapshots independently of the corpus
        uses: actions/cache/restore@55cc8345863c7cc4c66a329aec7e433d2d1c52a9
        with:
          path: packages/${{ matrix.target.package }}/fuzz/coverage/${{ matrix.target.database }}
          key: sql-semantics-coverage-v1-${{ matrix.target.database }}-${{ env.MYSQL_VERSION }}-${{ github.run_id }}-${{ github.run_attempt }}
          restore-keys: sql-semantics-coverage-v1-${{ matrix.target.database }}-${{ env.MYSQL_VERSION }}-
      - name: Copy sql-faker seed plans into the corpus
        env:
          DATABASE: ${{ matrix.target.database }}
        run: |
          case "$DATABASE" in
            mysql) version="mysql-$MYSQL_VERSION" ;;
            pg) version='pg-17.2' ;;
            sqlite) version='sqlite-3.47.2' ;;
          esac
          mkdir -p "fuzz/corpus/$DATABASE"
          cp "../sql-faker/seeds/$DATABASE/$version/"* "fuzz/corpus/$DATABASE/"
      - name: Run PHP-Fuzzer
        env:
          FUZZ_MAX_RUNS: ${{ inputs.max_runs || '10000' }}
        run: |
          set -euo pipefail
          mkdir -p build/fuzz "fuzz/corpus/${{ matrix.target.database }}"
          php -d memory_limit=-1 vendor/bin/php-fuzzer fuzz "fuzz/${{ matrix.target.script }}" "fuzz/corpus/${{ matrix.target.database }}/" --timeout=60 \
            "--max-runs=$FUZZ_MAX_RUNS" 2>&1 | tee "build/fuzz/${{ matrix.target.database }}.log"
      - name: Open an issue for a finding
        if: always()
        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd
        env:
          FUZZ_PACKAGE: ${{ matrix.target.package }}
          FUZZ_DATABASE: ${{ matrix.target.database }}
          FUZZ_SCRIPT: ${{ matrix.target.script }}
        with:
          script: |
            const fs = require('node:fs');
            const path = require('node:path');
            const crypto = require('node:crypto');
            const database = process.env.FUZZ_DATABASE;
            const script = process.env.FUZZ_SCRIPT;
            const root = path.resolve('packages', process.env.FUZZ_PACKAGE);
            const logPath = path.join(root, `build/fuzz/${database}.log`);
            if (!fs.existsSync(logPath)) return;
            const log = fs.readFileSync(logPath, 'utf8');
            const finding = log.match(/^(?:CORPUS )?CRASH in (.+)!$/m);
            if (!finding) return;
            const input = fs.readFileSync(path.resolve(root, finding[1]));
            const hash = crypto.createHash('sha256').update(input).digest('hex');
            const marker = `<!-- sql-semantics-fuzz:${database}:${hash} -->`;
            const issues = await github.paginate(github.rest.issues.listForRepo, {
              ...context.repo, state: 'open', per_page: 100
            });
            if (issues.some(issue => !issue.pull_request && issue.body?.includes(marker))) return;
            const run = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;
            const body = [
              marker,
              `PHP-Fuzzer found a statement the ${database} semantic analysis cannot round-trip.`,
              `Commit: ${context.sha}`,
              `Workflow and input artifact: ${run} (sql-semantics-fuzz-${database})`,
              `Run from packages/${process.env.FUZZ_PACKAGE} after extracting the artifact:`,
              '```sh',
              `vendor/bin/php-fuzzer run-single fuzz/${script} '${finding[1]}'`,
              '```',
              `Input SHA-256: ${hash}`,
              '<details><summary>PHP-Fuzzer output</summary>',
              '', '```text', log.slice(-45000), '```', '</details>'
            ].join('\n\n');
            await github.rest.issues.create({
              ...context.repo,
              title: `[sql-semantics fuzz] ${database}: ${hash.slice(0, 12)}`,
              body
            });
      - name: Save the evolving corpus
        if: always()
        uses: actions/cache/save@55cc8345863c7cc4c66a329aec7e433d2d1c52a9
        with:
          path: packages/${{ matrix.target.package }}/fuzz/corpus/${{ matrix.target.database }}
          key: sql-semantics-corpus-v1-${{ matrix.target.database }}-${{ env.MYSQL_VERSION }}-${{ github.run_id }}-${{ github.run_attempt }}
      - name: Save grammar coverage history
        if: always()
        uses: actions/cache/save@55cc8345863c7cc4c66a329aec7e433d2d1c52a9
        with:
          path: packages/${{ matrix.target.package }}/fuzz/coverage/${{ matrix.target.database }}
          key: sql-semantics-coverage-v1-${{ matrix.target.database }}-${{ env.MYSQL_VERSION }}-${{ github.run_id }}-${{ github.run_attempt }}
      - name: Upload PHP-Fuzzer inputs, output and grammar coverage
        if: always()
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a
        with:
          name: sql-semantics-fuzz-${{ matrix.target.database }}
          path: |
            packages/${{ matrix.target.package }}/crash-*
            packages/${{ matrix.target.package }}/timeout-*
            packages/${{ matrix.target.package }}/build/fuzz/${{ matrix.target.database }}.log
            packages/${{ matrix.target.package }}/fuzz/corpus/${{ matrix.target.database }}/
            packages/${{ matrix.target.package }}/fuzz/coverage/${{ matrix.target.database }}/
          if-no-files-found: ignore
          retention-days: 14

