48	/**
49	 * Container, grammar version and the statement rule to generate from. Statements start below
50	 * the grammar entry point, which also lists parser-internal selectors that PREPARE rejects.
51	 */
52	$containerMap = [
53	    '5.6.51' => [MySql56Container::class, 'mysql-5.6.51', 'statement'],
54	    '5.7.44' => [MySql57Container::class, 'mysql-5.7.44', 'statement'],
55	    '8.0.44' => [MySql80Container::class, 'mysql-8.0.44', 'simple_statement_or_begin'],
56	    '8.1.0'  => [MySql81Container::class, 'mysql-8.1.0', 'simple_statement_or_begin'],
57	    '8.2.0'  => [MySql82Container::class, 'mysql-8.2.0', 'simple_statement_or_begin'],
58	    '8.3.0'  => [MySql83Container::class, 'mysql-8.3.0', 'simple_statement_or_begin'],
59	    '8.4.7'  => [MySql84Container::class, 'mysql-8.4.7', 'simple_statement_or_begin'],
60	    '9.0.1'  => [MySql90Container::class, 'mysql-9.0.1', 'simple_statement_or_begin'],
61	    '9.1.0'  => [MySql91Container::class, 'mysql-9.1.0', 'simple_statement_or_begin'],
62	];
63	
64	if (!isset($containerMap[$mysqlVersion])) {
65	    fwrite(STDERR, "Unknown MySQL version: $mysqlVersion\n");
66	    fwrite(STDERR, 'Supported versions: ' . implode(', ', array_keys($containerMap)) . "\n");
67	    exit(1);
