100	/**
101	 * The plan compiler reads four budget bytes and then one decision per byte, so inputs
102	 * are allowed to grow well beyond php-fuzzer's default length.
103	 *
104	 * @var PhpFuzzer\Config $config
105	 */
106	$config->setAllowedExceptions([]);
107	$config->setMaxLen(80004);
108	$config->setTarget(static function (string $input) use ($provider, $planner, $constraints, $check): void {
109	    $plan = (new BytePlanCompiler())->compile($input, $planner, $constraints);
110	    $check->verify($provider->generate($plan), $input);
111	});
